PR="Extra practice"
def pq(id,stem,tstem,ok,opts,e_,eta,intro=None,tintro=None): qs(id,PR,intro or "Try this one. "+stem,tintro or "இதை முயலுங்கள். "+tstem,stem,tstem,ok,opts,e_,eta)
def O(a,ta,w=None,tw=None): return [a,ta,w,tw] if w else [a,ta]
step("pr-intro",PR,"Now for more practice, in the style of the textbook's Figure it Out exercises. Take your time. For each question, make the denominators equal first, or reduce to lowest terms, and check your answer against the explanation.","இப்போது பாடப்புத்தகத்தின் 'Figure it Out' பயிற்சிகள் போன்ற கூடுதல் பயிற்சி. நிதானமாகச் செய்யுங்கள். ஒவ்வொரு கேள்விக்கும் முதலில் பகுதிகளைச் சமமாக்குங்கள் அல்லது எளிய வடிவுக்குக் குறையுங்கள், பிறகு விளக்கத்துடன் உங்கள் விடையைச் சரிபாருங்கள்.",[CL,["write","tPz2",0.1,{"ms":900}]])
pq("pr1","2/7 + 5/7 + 6/7 =","2/7 + 5/7 + 6/7 =",1,[O("13/21","13/21","Do not add denominators.","பகுதிகளைக் கூட்டக் கூடாது."),O("13/7 = 1 6/7","13/7 = 1 6/7"),O("12/7","12/7","2 + 5 + 6 is 13, not 12.","2 + 5 + 6 = 13, 12 அல்ல.")],"2 + 5 + 6 = 13 sevenths = 13/7 = 1 6/7.","2 + 5 + 6 = 13 ஏழில் ஒன்று = 13/7 = 1 6/7.")
pq("pr2","3/4 + 1/3 =","3/4 + 1/3 =",2,[O("4/7","4/7","Never add the denominators.","பகுதிகளைக் கூட்டக் கூடாது."),O("4/12","4/12","The numerators must be changed to match 12 as well.","பகுதி 12 ஆனால் தொகுதிகளும் மாற வேண்டும்."),O("13/12 = 1 1/12","13/12 = 1 1/12")],"3/4 = 9/12, 1/3 = 4/12, sum = 13/12.","3/4 = 9/12, 1/3 = 4/12, கூட்டுத்தொகை 13/12.")
pq("pr3","2/3 + 5/6 =","2/3 + 5/6 =",0,[O("3/2 = 1 1/2","3/2 = 1 1/2"),O("7/9","7/9","Do not add numerators and denominators separately.","தொகுதிகளையும் பகுதிகளையும் தனித்தனியாகக் கூட்டக் கூடாது."),O("7/6","7/6","2/3 = 4/6, so the numerator is 4 + 5 = 9, not 7.","2/3 = 4/6, எனவே தொகுதி 4 + 5 = 9, 7 அல்ல.")],"4/6 + 5/6 = 9/6 = 3/2 = 1 1/2.","4/6 + 5/6 = 9/6 = 3/2 = 1 1/2.")
pq("pr4","3/4 + 1/3 + 1/5 =","3/4 + 1/3 + 1/5 =",1,[O("5/12","5/12","Do not add numerators and denominators separately.","தொகுதிகளையும் பகுதிகளையும் தனித்தனியாகக் கூட்டக் கூடாது."),O("77/60 = 1 17/60","77/60 = 1 17/60"),O("5/60","5/60","Each fraction needs converting to sixtieths: 45/60, 20/60, 12/60.","ஒவ்வொன்றையும் அறுபதில் ஒன்றாக மாற்றுங்கள்: 45/60, 20/60, 12/60.")],"45/60 + 20/60 + 12/60 = 77/60.","45/60 + 20/60 + 12/60 = 77/60.")
pq("pr5","5/6 - 4/9 =","5/6 - 4/9 =",2,[O("1/3","1/3","Do not subtract numerators and denominators separately.","தொகுதிகளையும் பகுதிகளையும் தனித்தனியாகக் கழிக்கக் கூடாது."),O("9/15","9/15","Do not add the numerators.","தொகுதிகளைக் கூட்டக் கூடாது."),O("7/18","7/18")],"5/6 = 15/18, 4/9 = 8/18. 15 - 8 = 7, so 7/18.","5/6 = 15/18, 4/9 = 8/18. 15 - 8 = 7, எனவே 7/18.")
pq("pr6","2/5 - 4/15 =","2/5 - 4/15 =",0,[O("2/15","2/15"),O("2/10","2/10","2/5 = 6/15. Then 6/15 - 4/15.","2/5 = 6/15. பிறகு 6/15 - 4/15."),O("6/15","6/15","6/15 is 2/5. We still need to subtract 4/15.","6/15 என்பது 2/5. இன்னும் 4/15 ஐக் கழிக்க வேண்டும்.")],"6/15 - 4/15 = 2/15.","6/15 - 4/15 = 2/15.")
pq("pr7","Which is greater, 8/3 or 5/2?","8/3 ஆ 5/2 ஆ, எது பெரியது?",0,[O("8/3","8/3"),O("5/2","5/2","In sixths: 5/2 = 15/6 and 8/3 = 16/6.","ஆறில்: 5/2 = 15/6, 8/3 = 16/6."),O("Equal","சமம்","16/6 and 15/6 are not equal.","16/6, 15/6 சமம் அல்ல.")],"8/3 = 16/6 and 5/2 = 15/6, so 8/3 is greater.","8/3 = 16/6, 5/2 = 15/6, எனவே 8/3 பெரியது.")
pq("pr8","Which is greater, 4/9 or 3/7?","4/9 ஆ 3/7 ஆ, எது பெரியது?",1,[O("3/7","3/7","4/9 = 28/63 and 3/7 = 27/63.","4/9 = 28/63, 3/7 = 27/63."),O("4/9","4/9"),O("Equal","சமம்","28/63 and 27/63 are not equal.","28/63, 27/63 சமம் அல்ல.")],"4/9 = 28/63 and 3/7 = 27/63, so 4/9 is greater.","4/9 = 28/63, 3/7 = 27/63, எனவே 4/9 பெரியது.")
pq("pr9","Which is greater, 7/10 or 9/14?","7/10 ஆ 9/14 ஆ, எது பெரியது?",0,[O("7/10","7/10"),O("9/14","9/14","7/10 = 49/70 and 9/14 = 45/70.","7/10 = 49/70, 9/14 = 45/70."),O("Equal","சமம்","49/70 and 45/70 are not equal.","49/70, 45/70 சமம் அல்ல.")],"49/70 > 45/70, so 7/10 is greater.","49/70 > 45/70, எனவே 7/10 பெரியது.")
pq("pr10","Arrange in descending order: 3/4, 12/5, 7/12, 5/4.","இறங்குவரிசையில் அடுக்குங்கள்: 3/4, 12/5, 7/12, 5/4.",2,[O("7/12, 3/4, 5/4, 12/5","7/12, 3/4, 5/4, 12/5","That is ascending order. Descending means largest first.","அது ஏறுவரிசை. இறங்குவரிசை என்றால் பெரியது முதலில்."),O("12/5, 3/4, 5/4, 7/12","12/5, 3/4, 5/4, 7/12","5/4 = 75/60 is bigger than 3/4 = 45/60.","5/4 = 75/60, 3/4 = 45/60 ஐ விடப் பெரியது."),O("12/5, 5/4, 3/4, 7/12","12/5, 5/4, 3/4, 7/12")],"In sixtieths: 144, 75, 45, 35. So 12/5, 5/4, 3/4, 7/12.","அறுபதில்: 144, 75, 45, 35. எனவே 12/5, 5/4, 3/4, 7/12.")
pq("pr11","Write 64/144 in lowest terms.","64/144 ஐ எளிய வடிவில் எழுதுங்கள்.",1,[O("32/72","32/72","32 and 72 are both still even. Keep dividing.","32 உம் 72 உம் இன்னும் இரட்டைப்படை. தொடர்ந்து வகுங்கள்."),O("4/9","4/9"),O("8/18","8/18","8 and 18 are both even. Divide again.","8 உம் 18 உம் இரட்டைப்படை. மீண்டும் வகுங்கள்.")],"Divide both by 16: 64 ÷ 16 = 4 and 144 ÷ 16 = 9. So 4/9.","இரண்டையும் 16 ஆல் வகுக்க: 64 ÷ 16 = 4, 144 ÷ 16 = 9. எனவே 4/9.")
pq("pr12","Write 19/6 as a mixed number.","19/6 ஐக் கலப்பு எண்ணாக எழுதுங்கள்.",0,[O("3 1/6","3 1/6"),O("1 3/6","1 3/6","19 ÷ 6 gives 3 wholes, not 1.","19 ÷ 6 = 3 முழுமை, 1 அல்ல."),O("3 6/1","3 6/1","The fractional part must be less than 1.","பின்னப் பகுதி 1 ஐ விடக் குறைவாக இருக்க வேண்டும்.")],"6 fits 3 times in 19 (18), remainder 1: 3 1/6.","19 க்குள் 6 மூன்று முறை (18), மீதி 1: 3 1/6.")

# ---- gap fill: Math Talk, number-line questions, sharing, teacher notes
MT="10 Math Talk and notes"
L("How many fractions lie between 0 and 1?","mtA",y=90,size=28,color="#1E88E5"); L("1/2, 1/3, 2/3, 1/10, 99/100 ... infinitely many","mtB",y=160,size=26,color="#2E7D32"); L("Between any two fractions there is always another one","mtC",y=230,size=26,color="#C0392B"); L("Example: between 1/2 and 3/4 lies 5/8 (halfway, in eighths)","mtD",y=300,size=24,color="#6A1B9A")
L("Group 1: 3 glasses among 4 children → 3/4 each","mtE",y=110,size=26,color="#1E88E5"); L("Group 2: 4 glasses among 7 children → 4/7 each","mtF",y=170,size=26,color="#E65100"); L("Common unit 28: 3/4 = 21/28 and 4/7 = 16/28","mtG",y=250,size=26,color="#2E7D32"); L("Group 1 children get more juice","mtH",y=330,size=30,color="#C0392B")
L("Teacher and parent note","mtI",y=90,size=28,color="#1E88E5"); L("Let children fold paper and share real things first","mtJ",y=160,size=24,color="#2E7D32"); L("Ask why, not only how: why do we need a common unit to add?","mtK",y=230,size=24,color="#E65100"); L("Use the number line to compare fractions","mtL",y=300,size=24,color="#6A1B9A"); L("Let children invent and swap problems","mtM",y=370,size=24,color="#C0392B")
step("x-between",MT,"Math Talk. How many fractions lie between 0 and 1? Think of one half, one third, two thirds, one tenth, ninety-nine hundredths. There is no end: between any two fractions there is always another one. For example, halfway between one half and three quarters, in eighths, we find five eighths. Discuss with your friends how you would find a fraction between any two fractions you choose.","கலந்துரையாடல். 0 க்கும் 1 க்கும் இடையில் எத்தனை பின்னங்கள் உள்ளன? 1/2, 1/3, 2/3, 1/10, 99/100 என நினைத்துப் பாருங்கள். முடிவே இல்லை: எந்த இரண்டு பின்னங்களுக்கு இடையிலும் எப்போதும் இன்னொரு பின்னம் உண்டு. உதாரணமாக 1/2 க்கும் 3/4 க்கும் நடுவில், எட்டில் வைத்துப் பார்த்தால் 5/8. நீங்கள் தேர்ந்தெடுக்கும் எந்த இரண்டு பின்னங்களுக்கு இடையிலும் ஒரு பின்னத்தை எப்படிக் காண்பீர்கள் என நண்பர்களுடன் பேசுங்கள்.",[CL]+[["write",i,round(0.1+k*0.2,2),{"ms":900}] for k,i in enumerate(["mtA","mtB","mtC","mtD"])])
qs("x-q1",MT,"Is there a fraction between 1/2 and 3/4?","1/2 க்கும் 3/4 க்கும் இடையில் ஒரு பின்னம் உண்டா?","Write both in eighths: 4/8 and 6/8:","இரண்டையும் எட்டில் எழுதுங்கள்: 4/8, 6/8:",1,[O("No, they are next to each other","இல்லை, அவை அடுத்தடுத்து","Between any two fractions there is always another.","எந்த இரண்டு பின்னங்களுக்கு இடையிலும் இன்னொன்று உண்டு."),O("Yes, 5/8","ஆம், 5/8"),O("Yes, 3/8","ஆம், 3/8","3/8 is smaller than 1/2.","3/8, 1/2 ஐ விடச் சிறியது.")],"5/8 lies between 4/8 and 6/8.","5/8, 4/8 க்கும் 6/8 க்கும் நடுவில் உள்ளது.")
step("x-juice",MT,"Sharing juice. Group 1 shares 3 glasses of sugarcane juice among 4 children, so each gets three quarters of a glass. Group 2 shares 4 glasses among 7 children, so each gets four sevenths. To compare, use the common unit one twenty-eighth: three quarters is 21 twenty-eighths and four sevenths is 16 twenty-eighths. So children in Group 1 get more.","சாறு பகிர்தல். குழு 1 இல் 3 டம்ளர் கரும்புச் சாறு 4 குழந்தைகளிடையே பகிரப்படுகிறது, ஒவ்வொருவருக்கும் 3/4 டம்ளர். குழு 2 இல் 4 டம்ளர் 7 குழந்தைகளிடையே, ஒவ்வொருவருக்கும் 4/7. ஒப்பிட 1/28 என்ற பொது அலகைப் பயன்படுத்துங்கள்: 3/4 = 21/28, 4/7 = 16/28. எனவே குழு 1 குழந்தைகளுக்கு அதிகம் கிடைக்கிறது.",[CL]+[["write",i,round(0.1+k*0.2,2),{"ms":900}] for k,i in enumerate(["mtE","mtF","mtG","mtH"])])
qs("x-q2",MT,"4 glasses of juice are shared equally among 5 children. How much does each get?","4 டம்ளர் சாறு 5 குழந்தைகளிடையே சமமாகப் பகிரப்படுகிறது. ஒவ்வொருவருக்கும் எவ்வளவு?","Glasses ÷ children:","டம்ளர் ÷ குழந்தைகள்:",0,[O("4/5 of a glass","4/5 டம்ளர்"),O("5/4 of a glass","5/4 டம்ளர்","That would be more than one glass each, but there are fewer glasses than children.","அது ஒவ்வொருவருக்கும் ஒரு டம்ளருக்கு மேல், ஆனால் குழந்தைகளை விடக் குறைவான டம்ளர்களே உள்ளன."),O("1/5 of a glass","1/5 டம்ளர்","That is for 1 glass shared among 5.","அது 1 டம்ளர் 5 பேரிடையே பகிர்வதற்கு.")],"4 ÷ 5 = 4/5.","4 ÷ 5 = 4/5.")
qs("x-q3",MT,"2 rotis are shared equally among 3 children. Each child gets:","2 ரொட்டிகள் 3 குழந்தைகளிடையே சமமாகப் பகிரப்படுகின்றன. ஒவ்வொருவருக்கும்:","Cut each roti into thirds:","ஒவ்வொரு ரொட்டியையும் மூன்றாக வெட்டுங்கள்:",2,[O("1/3 of a roti","1/3 ரொட்டி","That is only half of what each child gets.","அது ஒவ்வொருவருக்கும் கிடைப்பதில் பாதி மட்டுமே."),O("3/2 of a roti","3/2 ரொட்டி","That is more than a whole roti each.","அது ஒவ்வொருவருக்கும் ஒரு முழு ரொட்டியை விட அதிகம்."),O("2/3 of a roti","2/3 ரொட்டி")],"2 ÷ 3 = 2/3.","2 ÷ 3 = 2/3.")
step("x-notes",MT,"Notes for teachers and parents. Let children fold paper strips and share real things before using symbols. Ask why, not only how: why do we need a common unit to add? Use the number line to compare fractions. And encourage children to make their own fraction problems and swap them with friends.","ஆசிரியர்கள், பெற்றோருக்கான குறிப்புகள். குறியீடுகளைப் பயன்படுத்தும் முன் குழந்தைகள் காகிதப் பட்டைகளை மடித்து, உண்மையான பொருட்களைப் பகிர்ந்து பார்க்கட்டும். எப்படி என்பதோடு ஏன் என்றும் கேளுங்கள்: கூட்டுவதற்கு ஏன் பொது அலகு தேவை? பின்னங்களை ஒப்பிட எண்கோட்டைப் பயன்படுத்துங்கள். குழந்தைகள் தங்கள் சொந்தப் பின்னக் கணக்குகளை உருவாக்கி நண்பர்களுடன் மாற்றிக்கொள்ளுங்கள்.",[CL]+[["write",i,round(0.1+k*0.15,2),{"ms":900}] for k,i in enumerate(["mtI","mtJ","mtK","mtL","mtM"])])

FX="11 Figure it out"
qs("fx-f1",FX,'Try this one. How many whole units are in 17/5?','இதை முயலுங்கள். 17/5 இல் எத்தனை முழு அலகுகள்?','How many whole units are in 17/5?','17/5 இல் எத்தனை முழு அலகுகள்?',1,[O('2','2','2 is the remainder, not the whole units.','2 மீதி, முழு அலகுகள் அல்ல.'),O('3','3'),O('5','5','5 is the denominator.','5 பகுதி எண்.')],'17/5 = 3 2/5.','17/5 = 3 2/5.')
qs("fx-f2",FX,'Try this one. Write 25/8 as a mixed number.','இதை முயலுங்கள். 25/8 ஐக் கலப்பு எண்ணாக எழுதுங்கள்.','Write 25/8 as a mixed number.','25/8 ஐக் கலப்பு எண்ணாக எழுதுங்கள்.',0,[O('3 1/8','3 1/8'),O('1 3/8','1 3/8','The whole number is 3, not 1.','முழு எண் 3, 1 அல்ல.'),O('3 8/1','3 8/1','The fraction part is 1/8.','பின்னப் பகுதி 1/8.')],'25 ÷ 8 = 3 remainder 1.','25 ÷ 8 = 3 remainder 1.')
qs("fx-f3",FX,'Try this one. Which fraction is equivalent to 2/6?','இதை முயலுங்கள். 2/6 க்குச் சமமான பின்னம் எது?','Which fraction is equivalent to 2/6?','2/6 க்குச் சமமான பின்னம் எது?',2,[O('2/3','2/3','2/3 is the same as 4/6, not 2/6.','2/3 என்பது 4/6 க்குச் சமம், 2/6 க்கு அல்ல.'),O('1/6','1/6','Divide the bottom by 2 as well.','பகுதியையும் 2 ஆல் வகுங்கள்.'),O('1/3','1/3')],'2/6 = 1/3.','2/6 = 1/3.')
qs("fx-f4",FX,'Try this one. How many pieces of length 1/6 make a length of 1/3?','இதை முயலுங்கள். 1/6 நீளத் துண்டுகள் எத்தனை சேர்ந்தால் 1/3 நீளம்?','How many pieces of length 1/6 make a length of 1/3?','1/6 நீளத் துண்டுகள் எத்தனை சேர்ந்தால் 1/3 நீளம்?',1,[O('1','1','One piece is only 1/6.','ஒரு துண்டு 1/6 மட்டுமே.'),O('2','2'),O('3','3','Three pieces make 1/2.','மூன்று துண்டுகள் 1/2 ஆகும்.')],'2 × 1/6 = 1/3.','2 × 1/6 = 1/3.')
qs("fx-f5",FX,'Try this one. Arrange in ascending order: 3/4, 5/8, 1/2.','இதை முயலுங்கள். ஏறுவரிசையில் அடுக்குங்கள்: 3/4, 5/8, 1/2.','Arrange in ascending order: 3/4, 5/8, 1/2.','ஏறுவரிசையில் அடுக்குங்கள்: 3/4, 5/8, 1/2.',0,[O('1/2, 5/8, 3/4','1/2, 5/8, 3/4'),O('3/4, 5/8, 1/2','3/4, 5/8, 1/2','That is descending order.','அது இறங்குவரிசை.'),O('5/8, 1/2, 3/4','5/8, 1/2, 3/4','4/8 is smaller than 5/8.','4/8, 5/8 ஐ விடச் சிறியது.')],'In eighths: 4/8 < 5/8 < 6/8.','In eighths: 4/8 < 5/8 < 6/8.')
qs("fx-f6",FX,'Try this one. 1/2 + 1/3 =','இதை முயலுங்கள். 1/2 + 1/3 =','1/2 + 1/3 =','1/2 + 1/3 =',2,[O('2/5','2/5','Do not add tops and bottoms separately.','தொகுதி, பகுதிகளைத் தனித்தனியாகக் கூட்டாதீர்கள்.'),O('2/6','2/6','3/6 + 2/6 is 5/6.','3/6 + 2/6 = 5/6.'),O('5/6','5/6')],'3/6 + 2/6 = 5/6.','3/6 + 2/6 = 5/6.')
qs("fx-f7",FX,'Try this one. Geeta bought 2/5 m of lace and Shamim 3/4 m. How much lace in all?','இதை முயலுங்கள். கீதா 2/5 மீ, ஷமீம் 3/4 மீ நாடா வாங்கினர். மொத்தம்?','Geeta bought 2/5 m of lace and Shamim 3/4 m. How much lace in all?','கீதா 2/5 மீ, ஷமீம் 3/4 மீ நாடா வாங்கினர். மொத்தம்?',1,[O('5/9 m','5/9 மீ','Do not add numerators and denominators separately.','தொகுதி, பகுதிகளைத் தனித்தனியாகக் கூட்டாதீர்கள்.'),O('23/20 m','23/20 மீ'),O('17/20 m','17/20 மீ','8 + 15 is 23, not 17.','8 + 15 = 23, 17 அல்ல.')],'8/20 + 15/20 = 23/20.','8/20 + 15/20 = 23/20.')
qs("fx-f8",FX,'Try this one. 7/8 - 1/4 =','இதை முயலுங்கள். 7/8 - 1/4 =','7/8 - 1/4 =','7/8 - 1/4 =',0,[O('5/8','5/8'),O('6/4','6/4','Do not subtract tops and bottoms separately.','தொகுதி, பகுதிகளைத் தனித்தனியாகக் கழிக்காதீர்கள்.'),O('6/8','6/8','Subtract 2, not 1, from 7.','7 இலிருந்து 2 ஐக் கழியுங்கள், 1 அல்ல.')],'7/8 - 2/8 = 5/8.','7/8 - 2/8 = 5/8.')
qs("fx-f9",FX,'Try this one. Rahim mixes 2 1/2 litres yellow paint with 3 litres blue. How much paint?','இதை முயலுங்கள். ரஹீம் 2 1/2 லிட்டர் மஞ்சளுடன் 3 லிட்டர் நீலம் கலக்கிறான். மொத்தம்?','Rahim mixes 2 1/2 litres yellow paint with 3 litres blue. How much paint?','ரஹீம் 2 1/2 லிட்டர் மஞ்சளுடன் 3 லிட்டர் நீலம் கலக்கிறான். மொத்தம்?',2,[O('5 litres','5 லிட்டர்','The half litre must be counted too.','அரை லிட்டரையும் சேர்க்க வேண்டும்.'),O('6 litres','6 லிட்டர்','The exact sum is 5 1/2, not 6.','சரியான கூட்டுத்தொகை 5 1/2, 6 அல்ல.'),O('5 1/2 litres','5 1/2 லிட்டர்')],'2 + 3 = 5, plus the half.','2 + 3 = 5, plus the half.')
qs("fx-f10",FX,'Try this one. Three rotis are shared equally among 4 children. What fraction of a roti does each get?','இதை முயலுங்கள். மூன்று ரொட்டிகள் 4 குழந்தைகளிடையே பகிரப்படுகின்றன. ஒவ்வொருவருக்கும்?','Three rotis are shared equally among 4 children. What fraction of a roti does each get?','மூன்று ரொட்டிகள் 4 குழந்தைகளிடையே பகிரப்படுகின்றன. ஒவ்வொருவருக்கும்?',1,[O('4/3','4/3','That is more than one roti each.','அது ஒரு ரொட்டியை விட அதிகம்.'),O('3/4','3/4'),O('1/4','1/4','That is for one roti shared among 4.','அது ஒரு ரொட்டி 4 பேருக்கு.')],'3 ÷ 4 = 3/4.','3 ÷ 4 = 3/4.')

import math as _mf
CK="12 Chikki and circles"
def RAW(id,d): part("raw",id,d)
def PLY(id,pts,fill,stroke="#16253F",w=3): RAW(id,{"kind":"poly","points":[[round(a,1),round(b,1)] for a,b in pts],"fill":fill,"stroke":stroke,"width":w})
def LNE(id,x1,y1,x2,y2,c="#78909C",w=2): RAW(id,{"kind":"line","x1":round(x1,1),"y1":round(y1,1),"x2":round(x2,1),"y2":round(y2,1),"stroke":c,"width":w})
cw=24
# whole chikki 6 x 4 cells
RAW("ckW",{"kind":"rect","x":380,"y":150,"w":6*cw*2,"h":4*cw*2,"fill":"#E0A458","stroke":"#8D5524","width":4,"rx":6})
for k in range(1,6): LNE("ckv%d"%k,380+k*cw*2,150,380+k*cw*2,150+4*cw*2,"#8D5524",2)
for k in range(1,4): LNE("ckh%d"%k,380,150+k*cw*2,380+6*cw*2,150+k*cw*2,"#8D5524",2)
L("A whole chikki: 6 × 4 = 24 equal squares","ckT",y=100,size=26,color="#1E5FA8"); L("Each little square is 1/24 of the whole chikki","ckU",y=400,size=26,color="#C0392B")
step("ck-whole",CK,"Here is a whole chikki. Count its little squares: 6 across and 4 down, so 24 equal squares. Each little square is one twenty-fourth of the whole chikki. Now we can find any piece: count how many little squares it covers, and write that number over 24.","இதோ ஒரு முழு சிக்கி. சிறு சதுரங்களை எண்ணுங்கள்: குறுக்கே 6, கீழே 4, மொத்தம் 24 சம சதுரங்கள். ஒவ்வொரு சிறு சதுரமும் முழுச் சிக்கியின் 1/24. இப்போது எந்தத் துண்டையும் காணலாம்: அது எத்தனை சிறு சதுரங்களை மூடுகிறது என எண்ணி, அந்த எண்ணை 24 க்கு மேல் எழுதுங்கள்.",[CL]+[["write","ckT",0.05,{"ms":900}],["show","ckW",0.2,{"ms":400}]]+[["show","ckv%d"%k,0.3+k*0.03,{"ms":150}] for k in range(1,6)]+[["show","ckh%d"%k,0.5+k*0.03,{"ms":150}] for k in range(1,4)]+[["write","ckU",0.8,{"ms":900}]])
pieces=[("a",[(0,0),(1,0),(1,2),(0,2)],"1/12",2),("b",[(0,0),(3,0),(0,4)],"1/4",6),("c",[(0,0),(3,0),(0,2)],"1/8",3),("d",[(0,0),(1,0),(1,4),(0,4)],"1/6",4),
("e",[(0,0),(2,0),(2,1),(1,1),(1,2),(0,2)],"1/8",3),("f",[(0,0),(0,4),(2,2)],"1/6",4),("g",[(0,0),(1,0),(1,1),(0,1)],"1/24",1),("h",[(0,0),(1,0),(0,2)],"1/24",1)]
for i,(nm,pts,fr,cells) in enumerate(pieces):
    x0=70+(i%4)*210; yb=(250 if i<4 else 430)
    PLY("cp"+nm,[(x0+a*cw*1.0,yb-b*cw*1.0) for a,b in pts],"#E0A458","#8D5524",3)
    L(f"{nm}  {fr}","cl"+nm,y=yb+32,size=26,color="#1E5FA8",x=x0+40)
L("Whole chikki = 24 squares","ckZ",y=60,size=24,color="#C0392B")
step("ck-pieces",CK,"How much of the whole chikki is each piece? Count the squares it covers, and write it over 24. Piece a covers 2 squares: two twenty-fourths, which is one twelfth. Piece b covers 6 squares: one quarter. Piece c covers 3 squares: one eighth. Piece d covers 4 squares: one sixth. Piece e is 3 squares: one eighth. Piece f is 4 squares: one sixth. Pieces g and h are each 1 square: one twenty-fourth. Different shapes can have the same fraction.","ஒவ்வொரு துண்டும் முழுச் சிக்கியின் எவ்வளவு? அது மூடும் சதுரங்களை எண்ணி 24 க்கு மேல் எழுதுங்கள். a: 2 சதுரம் = 2/24 = 1/12. b: 6 சதுரம் = 1/4. c: 3 சதுரம் = 1/8. d: 4 சதுரம் = 1/6. e: 3 சதுரம் = 1/8. f: 4 சதுரம் = 1/6. g, h: தலா 1 சதுரம் = 1/24. வெவ்வேறு வடிவங்களுக்கும் ஒரே பின்னம் இருக்கலாம்.",[CL]+[["write","ckZ",0.02,{"ms":700}]]+[["show","cp"+nm,0.08+i*0.1,{"ms":250}] for i,(nm,_,_,_) in enumerate(pieces)]+[["write","cl"+nm,0.1+i*0.1,{"ms":700}] for i,(nm,_,_,_) in enumerate(pieces)])
def ckq(id,stem,ts,ok,opts,e,et): qs(id,CK,stem,ts,stem,ts,ok,opts,e,et,[CL]+[["show","cp"+nm,0.05+i*0.04,{"ms":200}] for i,(nm,_,_,_) in enumerate(pieces)])
ckq("ck-q1","A piece covers 6 of the 24 squares of a chikki. What fraction of the whole chikki is it?","ஒரு துண்டு சிக்கியின் 24 சதுரங்களில் 6 ஐ மூடுகிறது. அது முழுச் சிக்கியின் எந்தப் பின்னம்?",1,[O("6/4","6/4","The whole has 24 squares, so 24 goes below.","முழுவதும் 24 சதுரங்கள், எனவே 24 கீழே வரும்."),O("1/4","1/4"),O("1/6","1/6","1/6 is 4 squares, not 6.","1/6 என்பது 4 சதுரங்கள், 6 அல்ல.")],"6/24 = 1/4.","6/24 = 1/4.")
ckq("ck-q2","Piece d is 4 squares and piece f is 4 squares, with different shapes. Which is bigger?","துண்டு d 4 சதுரம், துண்டு f 4 சதுரம், வடிவங்கள் வேறு. எது பெரியது?",2,[O("d","d","Both cover 4 squares.","இரண்டும் 4 சதுரங்களை மூடுகின்றன."),O("f","f","Both cover 4 squares.","இரண்டும் 4 சதுரங்களை மூடுகின்றன."),O("They are equal: 1/6 each","சமம்: ஒவ்வொன்றும் 1/6")],"Same number of squares means the same fraction.","சம சதுரங்கள் என்றால் சம பின்னம்.")
# circles with 8, 5, 3, 6 equal parts, one shaded
for i,(n,fr) in enumerate([(8,"1/8"),(5,"1/5"),(3,"1/3"),(6,"1/6")]):
    cx=120+i*220; cy=220; r=80
    RAW("cc%d"%i,{"kind":"circle","cx":cx,"cy":cy,"r":r,"fill":"#FFFFFF","stroke":"#16253F","width":4})
    a0=90; a1=90+360/n
    PLY("cs%d"%i,[(cx,cy)]+[(cx+r*_mf.cos(_mf.radians(a0+(a1-a0)*t/6)),cy-r*_mf.sin(_mf.radians(a0+(a1-a0)*t/6))) for t in range(7)],"#FFB74D","#16253F",3)
    for k in range(n): LNE("cd%dx%d"%(i,k),cx,cy,cx+r*_mf.cos(_mf.radians(90+k*360/n)),cy-r*_mf.sin(_mf.radians(90+k*360/n)),"#16253F",3)
    L(f"{n} equal parts","cn%d"%i,y=cy+r+34,size=22,color="#1E5FA8",x=cx)
    L(fr,"cf%d"%i,y=cy+r+68,size=30,color="#C0392B",x=cx)
L("Match each fractional unit with its picture","cmT",y=70,size=26,color="#1E5FA8")
step("ck-match",CK,"Match each fractional unit with the right picture. The circle cut into 8 equal parts has each part one eighth. With 5 equal parts, one fifth. With 3 equal parts, one third. With 6 equal parts, one sixth. The bottom number tells how many equal parts make the whole.","ஒவ்வொரு பின்ன அலகையும் சரியான படத்துடன் பொருத்துங்கள். 8 சம பாகங்கள் கொண்ட வட்டத்தின் ஒவ்வொரு பாகமும் 1/8. 5 சம பாகங்கள்: 1/5. 3 சம பாகங்கள்: 1/3. 6 சம பாகங்கள்: 1/6. கீழ் எண் முழுவதும் எத்தனை சம பாகங்கள் என்பதைச் சொல்கிறது.",[CL]+[["write","cmT",0.02,{"ms":700}]]+[x for i in range(4) for x in [["show","cc%d"%i,0.1+i*0.18,{"ms":200}],["show","cs%d"%i,0.13+i*0.18,{"ms":200}]]+[["show","cd%dx%d"%(i,k),0.14+i*0.18,{"ms":100}] for k in range(([8,5,3,6][i]))]+[["write","cn%d"%i,0.18+i*0.18,{"ms":500}],["write","cf%d"%i,0.2+i*0.18,{"ms":500}]]])
qs("ck-q3",CK,"Which fractional unit goes with a circle cut into 5 equal parts, one part shaded?","5 சம பாகங்களாகப் பிரிக்கப்பட்ட வட்டத்தில் ஒரு பாகம் நிழலிடப்பட்டால் எந்தப் பின்ன அலகு?","The bottom number counts equal parts:","கீழ் எண் சம பாகங்களை எண்ணும்:",0,[O("1/5","1/5"),O("1/6","1/6","1/6 needs 6 equal parts.","1/6 க்கு 6 சம பாகங்கள் வேண்டும்."),O("5/1","5/1","The shaded piece is one part, not five.","நிழலிட்டது ஒரு பாகம், ஐந்து அல்ல.")],"5 equal parts, 1 shaded: one fifth.","5 சம பாகங்கள், 1 நிழலிட்டது: ஐந்தில் ஒன்று.",[CL,["show","cc1",0.05,{"ms":200}],["show","cs1",0.08,{"ms":200}]]+[["show","cd1x%d"%k,0.1,{"ms":100}] for k in range(5)])

FW="13 Fraction wall"
RAW("fw1r",{"kind":"rect","x":150,"y":58,"w":600,"h":34,"fill":"#BBDEFB","stroke":"#FFFFFF","width":4,"rx":4}); L("1 whole","fw1t",y=83,size=20,color="#1F3B6E")
for n in range(2,11): part("fractionbar","fw%d"%n,{"n":n,"x":150,"y":58+(n-1)*38,"w":600,"h":34})
RAW("fwh",{"kind":"line","x1":450,"y1":50,"x2":450,"y2":445,"stroke":"#C0392B","width":4})
L("1 UNIT at the top, then halves, thirds ... tenths","fwT",y=452,size=20,color="#1E5FA8"); L("The red line at 1/2 passes through 1/2, 2/4, 3/6, 4/8 and 5/10","fwU",y=482,size=20,color="#C0392B")
step("fw-wall",FW,"This is the fraction wall, from one whole unit down to tenths. Each row is the same total length, cut into equal parts. Look at the red line through the middle. It passes the end of one half, two quarters, three sixths, four eighths and five tenths. They all reach the same length, so one half, two quarters, three sixths, four eighths and five tenths are equivalent fractions.","இது பின்னச் சுவர்: ஒரு முழு அலகிலிருந்து பத்தில் ஒன்று வரை. ஒவ்வொரு வரிசையும் ஒரே மொத்த நீளம், சம பாகங்களாகப் பிரிக்கப்பட்டது. நடுவே உள்ள சிவப்புக் கோட்டைப் பாருங்கள். அது 1/2, 2/4, 3/6, 4/8, 5/10 ஆகியவற்றின் முடிவைத் தொடுகிறது. எல்லாம் ஒரே நீளம், எனவே இவை சமமான பின்னங்கள்.",[CL]+[["write","fwT",0.02,{"ms":700}]]+[["show","fw1r",0.08,{"ms":250}],["show","fw1t",0.08,{"ms":250}]]+[x for n in range(2,11) for x in [["show","fw%d:frame"%n,0.08+n*0.05,{"ms":250}]]+[["show","fw%d:b%d"%(n,k),0.08+n*0.05,{"ms":250}] for k in range(1,n+1)]]+[["fill","fw%d:b%d"%(n,k),0.1+n*0.05,{"color":["#BBDEFB","#C8E6C9","#FFE0B2"][(k-1)%3]}] for n in range(2,11) for k in range(1,n+1)]+[["show","fwh",0.7,{"ms":400}],["write","fwU",0.85,{"ms":900}]])
def fwq(id,stem,ts,ok,opts,e,et): qs(id,FW,stem,ts,stem,ts,ok,opts,e,et,[CL]+[["show","fw1r",0.02,{"ms":150}],["show","fw1t",0.02,{"ms":150}]]+[x for n in range(2,11) for x in [["show","fw%d:frame"%n,0.02+n*0.02,{"ms":150}]]+[["show","fw%d:b%d"%(n,k),0.02+n*0.02,{"ms":150}] for k in range(1,n+1)]]+[["fill","fw%d:b%d"%(n,k),0.05+n*0.02,{"color":["#BBDEFB","#C8E6C9","#FFE0B2"][(k-1)%3]}] for n in range(2,11) for k in range(1,n+1)]+[["show","fwh",0.4,{"ms":200}]])
fwq("fw-q1","Are 3/6, 4/8 and 5/10 equivalent fractions?","3/6, 4/8, 5/10 சமமான பின்னங்களா?",0,[O("Yes, all equal 1/2","ஆம், எல்லாம் 1/2 க்குச் சமம்"),O("No, the numbers are different","இல்லை, எண்கள் வேறு","Different numbers can still reach the same length on the wall.","வேறு எண்கள் சுவரில் ஒரே நீளத்தை அடையலாம்."),O("Only 3/6 and 4/8","3/6, 4/8 மட்டும்","5/10 also reaches the red line.","5/10 உம் சிவப்புக் கோட்டை அடைகிறது.")],"All three reach the same length as 1/2.","மூன்றும் 1/2 ஆன அதே நீளத்தை அடைகின்றன.")
fwq("fw-q2","Which fraction on the wall has the same length as 2/4?","சுவரில் 2/4 க்கு அதே நீளம் கொண்ட பின்னம் எது?",2,[O("2/5","2/5","2/5 is shorter than half.","2/5, பாதியை விடக் குறைவு."),O("1/3","1/3","1/3 is shorter than half.","1/3, பாதியை விடக் குறைவு."),O("1/2","1/2")],"2/4 reaches the red line, the same as 1/2.","2/4 சிவப்புக் கோட்டை அடைகிறது, 1/2 போலவே.")
fwq("fw-q3","Write two fractions equivalent to 2/6.","2/6 க்குச் சமமான இரண்டு பின்னங்கள் எவை?",1,[O("2/12 and 3/6","2/12, 3/6","Both of these are different lengths from 2/6.","இரண்டும் 2/6 க்கு வேறு நீளம்."),O("1/3 and 4/12","1/3, 4/12"),O("2/3 and 4/8","2/3, 4/8","2/3 is double 2/6.","2/3 என்பது 2/6 இன் இரு மடங்கு.")],"2/6 = 1/3 = 4/12: multiply or divide top and bottom by the same number.","2/6 = 1/3 = 4/12: தொகுதி, பகுதி இரண்டையும் ஒரே எண்ணால் பெருக்கலாம்/வகுக்கலாம்.")

BL_="14 Lengths on the line"
x0,u=100,330
def ruler(pre,y,halves=False):
    LNE(pre+"ax",x0,y,x0+2*u+10,y,"#16253F",4)
    for k in range(0,11): LNE(pre+"tk%d"%k,x0+k*u/5,y-12,x0+k*u/5,y+12,"#16253F",3)
    for k,t in ((0,"0"),(5,"1"),(10,"2")): L(t,pre+"nm%d"%k,y=y+44,size=26,color="#16253F",x=x0+k*u/5)
def bar(id,y,f,col): RAW(id,{"kind":"rect","x":x0,"y":y,"w":round(f*u,1),"h":24,"fill":col,"stroke":col,"width":2,"rx":4})
ruler("ra",330)
bar("rab",120,0.5,"#1E88E5"); bar("rak",170,1.5,"#16253F")
L("blue = 1/2","rat1",y=137,size=22,color="#1E88E5",x=x0+u/2+100); L("black = 3/2, that is 1 1/2","rat2",y=225,size=22,color="#16253F",x=300)
def rul(pre): return [["show",pre+"ax",0.02,{"ms":300}]]+[["show",pre+"tk%d"%k,0.05+k*0.01,{"ms":150}] for k in range(11)]+[["show",pre+"nm%d"%k,0.2,{"ms":200}] for k in (0,5,10)]
step("n14-half",BL_,"The distance from 0 to 1 is one unit, divided into two equal parts, so each part is one half. The blue line is one half long. The black line reaches three of these halves, so its length is three halves, which is one and a half.","0 முதல் 1 வரை ஓர் அலகு, இரு சம பாகங்கள்; ஒவ்வொன்றும் அரை. நீலக் கோடு அரை நீளம். கருப்புக் கோடு மூன்று அரைகள்: 3/2, அதாவது ஒன்றரை.",[CL]+rul("ra")+[["show","rab",0.4,{"ms":500}],["show","rak",0.55,{"ms":600}],["write","rat1",0.8,{"ms":500}],["write","rat2",0.9,{"ms":600}]])
qs("n14-q1",BL_,"A black line reaches the 3rd half mark on a number line (each part is 1/2). What is its length?","கருப்புக் கோடு எண்கோட்டில் 3வது அரைக் குறியை அடைகிறது (ஒவ்வொரு பாகமும் 1/2). நீளம் என்ன?","3 halves:","3 அரைகள்:",1,[O("1/3","1/3","1/3 would need thirds, not halves.","1/3 க்கு மூன்றில் ஒன்றுகள் வேண்டும்."),O("3/2","3/2"),O("2/3","2/3","2/3 is smaller than 1.","2/3, 1 ஐ விடச் சிறியது.")],"3 × 1/2 = 3/2 = 1 1/2.","3 × 1/2 = 3/2 = 1 1/2.")
for i,(n,col) in enumerate([(9,"#16253F"),(8,"#37474F"),(7,"#546E7A"),(6,"#78909C")]): bar("rbk%d"%i,110+i*40,n/5,col); L("%d/5"%n,"rbl%d"%i,y=127+i*40,size=22,color="#C0392B",x=x0+n*u/5+60)
L("Each part is 1/5","rbT",y=70,size=22,color="#1E5FA8")
step("n14-fifths",BL_,"Now the unit from 0 to 1 is divided into five equal parts, so each part is one fifth. The shortest black bar ends at the sixth mark, so it is six fifths. The next ends at the seventh mark: seven fifths. Then eight fifths, and the longest is nine fifths. All of them are more than 1, because they pass the mark 1 at five fifths.","0 முதல் 1 வரை ஐந்து சம பாகங்கள்; ஒவ்வொன்றும் ஐந்தில் ஒன்று. மிகக் குறுகிய கருப்புப் பட்டை ஆறாவது குறியில் முடிகிறது: 6/5. அடுத்தது 7/5, பிறகு 8/5, நீளமானது 9/5. எல்லாம் 1 ஐக் கடந்துவிட்டதால் 1 ஐ விடப் பெரியவை.",[CL]+rul("ra")+[["write","rbT",0.35,{"ms":500}]]+[["show","rbk%d"%i,0.45+i*0.1,{"ms":400}] for i in (3,2,1,0)]+[["write","rbl%d"%i,0.55+(3-i)*0.1,{"ms":500}] for i in (3,2,1,0)])
qs("n14-q2",BL_,"A black bar ends at the 8th mark when each part is 1/5. How long is it?","ஒவ்வொரு பாகமும் 1/5 எனில் கருப்புப் பட்டை 8வது குறியில் முடிந்தால் நீளம் என்ன?","8 fifths:","8 ஐந்தில் ஒன்றுகள்:",0,[O("8/5","8/5"),O("5/8","5/8","5/8 is less than 1; the bar passes 1.","5/8 என்பது 1 ஐ விடக் குறைவு; பட்டை 1 ஐக் கடக்கிறது."),O("2/5","2/5","2/5 is only two parts.","2/5 என்பது இரண்டு பாகங்கள் மட்டும்.")],"8 × 1/5 = 8/5.","8 × 1/5 = 8/5.")

