for k in (0,5,10): L(["0","5/10","1"][k//5],"tllb%d"%k,y=372,size=20,color="#16253F",x=tx0+k*tu/10)
for i,(n,d,col,t) in enumerate([(1,10,"#1E88E5","1/10"),(3,10,"#E65100","3/10"),(4,5,"#2E7D32","4/5 = 8/10")]):
    RAW("tlb%d"%i,{"kind":"rect","x":tx0,"y":110+i*55,"w":round(tu*n/d,1),"h":26,"fill":col,"stroke":col,"width":2,"rx":4}); L(t,"tlt%d"%i,y=130+i*55,size=22,color=col,x=tx0+tu*n/d+70)
L("0 to 1 is cut into 10 equal parts: each part is 1/10","tlT",y=70,size=22,color="#1E5FA8")
step("n15-draw",BT_,"Let us draw lines of length one tenth, three tenths and four fifths on a number line. Cut the space from 0 to 1 into ten equal parts: each part is one tenth. A line of length one tenth is one part. Three tenths is three parts. For four fifths, notice that each fifth is two tenths, so four fifths is eight tenths. The line reaches the eighth mark.","எண்கோட்டில் பத்தில் ஒன்று, பத்தில் மூன்று, ஐந்தில் நான்கு நீளக் கோடுகளை வரைவோம். 0 முதல் 1 வரை பத்து சம பாகங்கள்: ஒவ்வொன்றும் 1/10. 1/10 ஒரு பாகம்; 3/10 மூன்று பாகங்கள். ஐந்தில் ஒன்று என்பது பத்தில் இரண்டு; எனவே 4/5 = 8/10; எட்டாவது குறி வரை.",[CL]+[["show","tlax",0.02,{"ms":300}]]+[["show","tltk%d"%k,0.05+k*0.01,{"ms":150}] for k in range(11)]+[["show","tllb%d"%k,0.2,{"ms":200}] for k in (0,5,10)]+[["write","tlT",0.3,{"ms":600}]]+[x for i in range(3) for x in [["show","tlb%d"%i,0.45+i*0.18,{"ms":500}],["write","tlt%d"%i,0.55+i*0.18,{"ms":500}]]])
qs("n15-q1",BT_,"On a number line cut into tenths, how many parts long is the line for 4/5?","பத்தில் பிரித்த எண்கோட்டில் 4/5 நீளக் கோடு எத்தனை பாகங்கள்?","Each fifth is 2 tenths:","ஒவ்வொரு 1/5 உம் 2/10:",2,[O("4 parts","4 பாகங்கள்","4 parts would be 4/10.","4 பாகங்கள் என்பது 4/10."),O("5 parts","5 பாகங்கள்","5 parts would be 5/10, which is a half.","5 பாகங்கள் என்பது 5/10 = பாதி."),O("8 parts","8 பாகங்கள்")],"4/5 = 8/10.","4/5 = 8/10.")
qs("n15-q2",BT_,"Which is longer: 3/10 or 1/2?","3/10 அல்லது 1/2: எது நீளமானது?","1/2 = 5/10:","1/2 = 5/10:",1,[O("3/10","3/10","3/10 is shorter than 5/10.","3/10, 5/10 ஐ விடக் குறைவு."),O("1/2","1/2"),O("They are equal","சமம்","3/10 and 5/10 are not equal.","3/10, 5/10 சமமல்ல.")],"1/2 = 5/10 is longer than 3/10.","1/2 = 5/10, 3/10 ஐ விட நீளம்.")
